<?php require_once __DIR__.'/../includes/bootstrap.php'; require_login(); $albums=$pdo->query('SELECT a.*,COUNT(t.id) track_count FROM albums a LEFT JOIN tracks t ON t.album_id=a.id GROUP BY a.id ORDER BY a.created_at DESC')->fetchAll(); render_header('Alben',true); ?><div class="d-flex justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1">Alben</h1><p class="text-body-secondary mb-0">Musikalben hochladen, gestalten und teilen.</p></div><a class="btn btn-primary" href="album_edit.php">Neues Album</a></div><div class="row g-4"><?php foreach($albums as $a):?><div class="col-sm-6 col-lg-4"><div class="card h-100 shadow-sm"><?php if($a['cover_file']):?><img src="<?=base_url('uploads/covers/'.$a['cover_file'])?>" class="card-img-top" style="aspect-ratio:1/1;object-fit:cover" alt=""><?php else:?><div class="cover-placeholder rounded-0">♪</div><?php endif?><div class="card-body"><h2 class="h5"><?=e($a['title'])?></h2><p class="text-body-secondary"><?=e($a['artist'])?> · <?=$a['track_count']?> Titel</p><div class="d-flex gap-2"><a class="btn btn-sm btn-primary" href="album_edit.php?id=<?=$a['id']?>">Verwalten</a><a class="btn btn-sm btn-outline-secondary" href="shares.php?album_id=<?=$a['id']?>">Freigaben</a></div></div></div></div><?php endforeach?><?php if(!$albums):?><div class="col-12"><div class="alert alert-info">Noch keine Alben vorhanden.</div></div><?php endif?></div><?php render_footer();
